package com.paulinho.lg;
import android.app.*;import android.os.*;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity implements Remote.Listener {
 final int BG=0xff10141e,CARD=0xff1c2433,FG=0xffeef3ff,ACCENT=0xff72dfb4;
 final Handler handler=new Handler(Looper.getMainLooper());final LinkedHashMap<String,Tv> devices=new LinkedHashMap<>();Remote remote;LinearLayout body,deviceList;TextView status,volume;Button searchButton;String currentStatus="Selecione uma TV para começar.";boolean searching=false,destroyed=false,muted=false;int tab=0;String activeId="";
 public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);remote=new Remote(this);load();show(0);search();}
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}GradientDrawable bg(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(14));return d;}
 TextView label(String s,int size,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(c);t.setPadding(dp(4),dp(8),dp(4),dp(8));return t;}void heading(String s){body.addView(label(s,19,ACCENT));}void note(String s){body.addView(label(s,14,0xffb2bed1));}LinearLayout row(){LinearLayout r=new LinearLayout(this);body.addView(r);return r;}
 Button button(LinearLayout r,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextColor(FG);b.setTextSize(14);b.setAllCaps(false);b.setBackground(bg(CARD));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(60),1);p.setMargins(dp(3),dp(4),dp(3),dp(4));r.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 void show(int selected){tab=selected;deviceList=null;volume=null;LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(dp(12),dp(12),dp(12),0);setContentView(root);TextView title=label("Controle LG",28,FG);title.setTypeface(null,Typeface.BOLD);root.addView(title);status=label(currentStatus,14,ACCENT);root.addView(status);LinearLayout nav=new LinearLayout(this);root.addView(nav);String[] tabs={"TVs","Controle","Mouse","Teclado"};for(int i=0;i<tabs.length;i++){final int n=i;Button b=button(nav,tabs[i],()->show(n));if(i==selected)b.setTextColor(ACCENT);}ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(12),0,dp(24));scroll.addView(body);if(selected==0)tvPage();else if(selected==1)controlPage();else if(selected==2)mousePage();else keyboardPage();}
 void tvPage(){heading("Suas TVs");note("TV e celular precisam estar na mesma rede. Na primeira conexão, aceite o pedido na tela da TV.");LinearLayout r=row();searchButton=button(r,searching?"Buscando…":"Buscar na rede",this::search);searchButton.setEnabled(!searching);button(r,"Adicionar por IP",this::manual);deviceList=new LinearLayout(this);deviceList.setOrientation(1);body.addView(deviceList);renderDevices();note("As TVs pareadas ficam salvas neste celular. Toque e segure uma TV para removê-la. Se não aparecer, confira LG Connect Apps / conexão por dispositivos móveis nas configurações da TV.");}
 void renderDevices(){if(deviceList==null)return;deviceList.removeAllViews();if(devices.isEmpty())deviceList.addView(label(searching?"Procurando TVs webOS…":"Nenhuma TV encontrada. Busque novamente ou informe o IP.",15,FG));for(Tv tv:devices.values()){Button b=new Button(this);b.setAllCaps(false);b.setTextColor(FG);b.setTextSize(16);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(dp(16),0,dp(16),0);b.setBackground(bg(CARD));b.setText(tv.name+"\n"+tv.host+" • "+(tv.key.isEmpty()?"Encontrada / parear":"Salva")+(activeId.equals(tv.id)&&remote.ready?" • conectada":""));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(86));p.setMargins(0,dp(5),0,dp(5));deviceList.addView(b,p);b.setOnClickListener(v->{activeId=tv.id;remote.connect(tv);});b.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("Remover "+tv.name+"?").setMessage("O pareamento salvo será apagado.").setPositiveButton("Remover",(d,w)->{devices.remove(tv.id);if(activeId.equals(tv.id)){remote.disconnect();activeId="";status("TV removida.");}save();renderDevices();}).setNegativeButton("Cancelar",null).show();return true;});}}
 void search(){if(searching)return;searching=true;if(searchButton!=null)searchButton.setEnabled(false);status("Buscando TVs na rede…");Discovery.search(this,new Discovery.Listener(){public void found(Tv tv){handler.post(()->{if(destroyed)return;Tv old=devices.get(tv.id);if(old==null)for(Tv t:devices.values())if(t.host.equals(tv.host)&&t.id.equals(t.host)){old=t;break;}if(old!=null){devices.remove(old.id);old.id=tv.id;old.name=tv.name;old.host=tv.host;devices.put(old.id,old);}else devices.put(tv.id,tv);save();renderDevices();});}public void done(String error){handler.post(()->{if(destroyed)return;searching=false;if(tab==0)show(0);status(error!=null?error:remote.ready?"Conectado • "+remote.tv.name:"Busca concluída. Selecione uma TV ou informe seu IP.");});}});}
 static boolean validIp(String s){String[] p=s.split("\\.",-1);if(p.length!=4)return false;try{for(String n:p)if(!n.matches("[0-9]{1,3}")||Integer.parseInt(n)>255)return false;return Integer.parseInt(p[0])>0&&Integer.parseInt(p[0])<224;}catch(Exception e){return false;}}
 void manual(){EditText input=new EditText(this);input.setHint("Ex.: 192.168.1.50");input.setInputType(android.text.InputType.TYPE_CLASS_PHONE);AlertDialog d=new AlertDialog.Builder(this).setTitle("IP da TV").setView(input).setPositiveButton("Adicionar",null).setNegativeButton("Cancelar",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String host=input.getText().toString().trim();if(!validIp(host)){input.setError("Informe um IPv4 válido.");return;}Tv tv=null;for(Tv t:devices.values())if(t.host.equals(host))tv=t;if(tv==null){tv=new Tv(host,"LG webOS • "+host,host);devices.put(tv.id,tv);save();renderDevices();}activeId=tv.id;remote.connect(tv);d.dismiss();}));d.show();}
 void key(LinearLayout r,String label,String name){button(r,label,()->remote.button(name));}void cmd(LinearLayout r,String label,String uri){button(r,label,()->remote.command(uri));}
 void controlPage(){heading("Navegação");LinearLayout r=row();key(r,"Início","HOME");key(r,"↑","UP");key(r,"Menu","MENU");r=row();key(r,"←","LEFT");button(r,"OK",()->remote.click());key(r,"→","RIGHT");r=row();key(r,"Voltar","BACK");key(r,"↓","DOWN");key(r,"Sair","EXIT");heading("Som e canais");volume=label("Volume: —",16,FG);body.addView(volume);r=row();cmd(r,"Volume −","audio/volumeDown");button(r,"Mudo",()->remote.request("ssap://audio/setMute",Remote.obj("mute",!muted),"mudo"));cmd(r,"Volume +","audio/volumeUp");r=row();cmd(r,"Canal −","tv/channelDown");button(r,"Canais",()->remote.request("ssap://tv/getChannelList",new JSONObject(),"channels"));cmd(r,"Canal +","tv/channelUp");heading("Reprodução");r=row();cmd(r,"⏪","media.controls/rewind");cmd(r,"▶","media.controls/play");cmd(r,"⏸","media.controls/pause");cmd(r,"⏩","media.controls/fastForward");r=row();cmd(r,"Parar","media.controls/stop");button(r,"Entradas HDMI",()->remote.request("ssap://tv/getExternalInputList",new JSONObject(),"inputs"));button(r,"Apps",()->remote.request("ssap://com.webos.applicationManager/listApps",new JSONObject(),"apps"));heading("Teclas numéricas");for(int start=1;start<=7;start+=3){r=row();for(int i=start;i<start+3;i++)key(r,""+i,""+i);}r=row();key(r,"Guia","GUIDE");key(r,"0","0");key(r,"Info","INFO");r=row();String[] colors={"RED","GREEN","YELLOW","BLUE"};int[] values={0xffff7070,ACCENT,0xffffd166,0xff72aaff};for(int i=0;i<4;i++){String name=colors[i];Button b=button(r,"●",()->remote.button(name));b.setTextColor(values[i]);b.setContentDescription(name);}r=row();button(r,"Desligar TV",()->new AlertDialog.Builder(this).setTitle("Desligar a TV?").setPositiveButton("Desligar",(d,w)->remote.command("system/turnOff")).setNegativeButton("Cancelar",null).show());button(r,"Ligar TV",this::wake);r=row();button(r,"Desconectar",()->{remote.disconnect();status("Desconectado. Sua TV continua salva.");});note("Para ligar por rede, configure o MAC da TV e habilite a opção de ligar por Wi-Fi/rede na TV. Alguns comandos dependem do modelo e do app aberto.");if(remote.ready)remote.request("ssap://audio/getVolume",new JSONObject(),"volume");}
 void mousePage(){heading("Touchpad");note("Deslize um dedo para mover. Toque para clicar; dois dedos para rolar.");TextView pad=label("Deslize aqui\n\nToque = OK",23,FG);pad.setGravity(Gravity.CENTER);pad.setBackground(bg(CARD));body.addView(pad,new LinearLayout.LayoutParams(-1,dp(290)));pad.setOnTouchListener(new View.OnTouchListener(){float x,y,total,scroll;long down,last;public boolean onTouch(View v,MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:x=e.getX();y=e.getY();total=0;scroll=0;down=System.currentTimeMillis();last=0;v.getParent().requestDisallowInterceptTouchEvent(true);return true;case MotionEvent.ACTION_POINTER_DOWN:total=100;x=e.getX();y=e.getY();return true;case MotionEvent.ACTION_MOVE:float dx=e.getX()-x,dy=e.getY()-y;total+=Math.abs(dx)+Math.abs(dy);if(System.currentTimeMillis()-last>25){if(remote.ready){if(e.getPointerCount()>1){scroll+=dy;if(Math.abs(scroll)>dp(12)){remote.scroll(scroll>0?-1:1);scroll=0;}}else remote.move(dx/getResources().getDisplayMetrics().density*1.8f,dy/getResources().getDisplayMetrics().density*1.8f);}x=e.getX();y=e.getY();last=System.currentTimeMillis();}return true;case MotionEvent.ACTION_POINTER_UP:x=e.getX();y=e.getY();return true;case MotionEvent.ACTION_UP:if(total<dp(12)&&System.currentTimeMillis()-down<500)remote.click();v.getParent().requestDisallowInterceptTouchEvent(false);return true;case MotionEvent.ACTION_CANCEL:v.getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}});LinearLayout r=row();button(r,"Rolar ↑",()->remote.scroll(1));button(r,"Clique / OK",()->remote.click());button(r,"Rolar ↓",()->remote.scroll(-1));r=row();key(r,"Voltar","BACK");key(r,"Início","HOME");}
 void wake(){Tv tv=devices.get(activeId);if(tv==null){status("Selecione uma TV na lista primeiro.");return;}EditText input=new EditText(this);input.setHint("AA:BB:CC:DD:EE:FF");input.setText(tv.mac);AlertDialog d=new AlertDialog.Builder(this).setTitle("Ligar TV por rede").setMessage("Informe o endereço MAC da conexão de rede da TV. Habilite a opção de ligar por rede na LG; disponibilidade depende do modelo e da rede.").setView(input).setPositiveButton("Ligar",null).setNegativeButton("Cancelar",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String mac=input.getText().toString().trim().replace('-',':');if(!mac.matches("(?i)([0-9a-f]{2}:){5}[0-9a-f]{2}")){input.setError("MAC inválido.");return;}tv.mac=mac;save();d.dismiss();new Thread(()->{try{byte[] bytes=new byte[102];java.util.Arrays.fill(bytes,0,6,(byte)255);String[] parts=mac.split(":");for(int i=6;i<102;i++)bytes[i]=(byte)Integer.parseInt(parts[(i-6)%6],16);try(java.net.DatagramSocket socket=new java.net.DatagramSocket()){socket.setBroadcast(true);for(int port:new int[]{9,7})socket.send(new java.net.DatagramPacket(bytes,bytes.length,java.net.InetAddress.getByName("255.255.255.255"),port));}status("Pedido de ligar enviado. Aguarde e selecione a TV na lista.");}catch(Exception e){status("Não foi possível enviar o pedido de ligar.");}},"lg-wake").start();}));d.show();}
 void keyboardPage(){heading("Digite na TV");note("Abra um campo de texto na TV antes de enviar. Alguns apps usam um teclado próprio e não aceitam texto remoto.");EditText input=new EditText(this);input.setTextColor(FG);input.setHintTextColor(0xffa5b1c5);input.setHint("Texto para enviar à TV");input.setMinLines(3);input.setGravity(Gravity.TOP);body.addView(input,new LinearLayout.LayoutParams(-1,dp(145)));LinearLayout r=row();button(r,"Enviar texto",()->{String text=input.getText().toString();if(!text.isEmpty())remote.request("ssap://com.webos.service.ime/insertText",Remote.obj("text",text,"replace",0),"texto");});cmd(r,"Enter","com.webos.service.ime/sendEnterKey");r=row();button(r,"Apagar na TV",()->remote.request("ssap://com.webos.service.ime/deleteCharacters",Remote.obj("count",1),"apagar"));button(r,"Limpar aqui",()->input.setText(""));}
 public void status(String text){handler.post(()->{if(destroyed)return;currentStatus=text;if(status!=null)status.setText(text);});}public void paired(Tv tv){handler.post(()->{if(destroyed)return;devices.put(tv.id,tv);save();show(1);});}
 public void data(String kind,JSONObject p){handler.post(()->{if(destroyed)return;if(kind.equals("volume")){JSONObject value=p.optJSONObject("volumeStatus");if(value==null)value=p;muted=value.optBoolean("mute",value.optBoolean("muted",false));if(volume!=null)volume.setText("Volume: "+value.optInt("volume",0)+(muted?" • mudo":""));}else if(kind.equals("inputs"))choose(p.optJSONArray("devices"),"Entradas","label","id","tv/switchInput","inputId");else if(kind.equals("apps"))choose(p.optJSONArray("apps"),"Aplicativos","title","id","system.launcher/launch","id");else if(kind.equals("channels"))choose(p.optJSONArray("channelList"),"Canais","channelName","channelId","tv/openChannel","channelId");});}
 void choose(JSONArray a,String title,String label,String id,String uri,String field){if(a==null||a.length()==0){status("A TV não retornou itens para "+title.toLowerCase()+".");return;}String[] names=new String[a.length()];for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);names[i]=j==null?"—":j.optString(label,j.optString(id));}new AlertDialog.Builder(this).setTitle(title).setItems(names,(d,w)->{JSONObject j=a.optJSONObject(w);if(j!=null)remote.request("ssap://"+uri,Remote.obj(field,j.optString(id)),title);}).setNegativeButton("Fechar",null).show();}
 void load(){try{JSONArray a=new JSONArray(getSharedPreferences("tvs",0).getString("list","[]"));for(int i=0;i<a.length();i++){Tv t=new Tv(a.getJSONObject(i));devices.put(t.id,t);}}catch(Exception ignored){}}void save(){JSONArray a=new JSONArray();for(Tv t:devices.values())a.put(t.json());getSharedPreferences("tvs",0).edit().putString("list",a.toString()).apply();}
 protected void onDestroy(){destroyed=true;handler.removeCallbacksAndMessages(null);remote.disconnect();super.onDestroy();}
}
